export function solve(hetu: string): boolean {
  // DDMMYY + century sign + 3-digit individual number + check character
  const m = /^(\d{2})(\d{2})(\d{2})([+\-Aa])(\d{3})([0-9A-Z])$/.exec(hetu);
  if (!m) return false;

  const [, dd, mm, yy, century, indiv, check] = m;

  // Century sign: + = 1800s, - = 1900s, A/a = 2000s
  const base = century === "+" ? 1800 : century === "-" ? 1900 : 2000;
  const day = Number(dd);
  const month = Number(mm);
  const year = base + Number(yy);

  // Validate the calendar date
  if (month < 1 || month > 12) return false;
  const leap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const daysInMonth = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (day < 1 || day > daysInMonth[month - 1]) return false;

  // Individual number range
  const n = Number(indiv);
  if (n < 2 || n > 899) return false;

  // Check character: DDMMYYNNN as integer, modulo 31, mapped to the control table
  const chars = "0123456789ABCDEFHJKLMNPRSTUVWXY";
  const num = Number(dd + mm + yy + indiv);
  return chars[num % 31] === check;
}

export function solve(cnp: string): boolean {
  // Must be exactly 13 digits
  if (!/^\d{13}$/.test(cnp)) return false;

  // Codes starting with 9000 are accepted without further checks
  if (cnp.startsWith("9000")) return true;

  const digits = cnp.split("").map(Number);

  // Sex/century digit
  const s = digits[0];
  if (s === 0) return false;

  const yy = digits[1] * 10 + digits[2];
  const mm = digits[3] * 10 + digits[4];
  const dd = digits[5] * 10 + digits[6];

  // Determine whether February 29 is allowed
  let feb29Allowed: boolean;
  if (s >= 1 && s <= 6) {
    let year: number;
    if (s === 1 || s === 2) year = 1900 + yy;
    else if (s === 3 || s === 4) year = 1800 + yy;
    else year = 2000 + yy;
    feb29Allowed = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  } else {
    // 7, 8, 9: checked on the two-digit year alone
    feb29Allowed = yy % 4 === 0;
  }

  // Validate month and day
  if (mm < 1 || mm > 12) return false;
  const daysInMonth = [31, feb29Allowed ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (dd < 1 || dd > daysInMonth[mm - 1]) return false;

  // Check digit
  const weights = [2, 7, 9, 1, 4, 6, 3, 5, 8, 2, 7, 9];
  let sum = 0;
  for (let i = 0; i < 12; i++) {
    sum += digits[i] * weights[i];
  }
  let check = sum % 11;
  if (check === 10) check = 1;

  return check === digits[12];
}

export function solve(id: string): boolean {
  const match = /^(\d{2})(\d{2})(\d{2})\/?(\d{3,4})$/.exec(id);
  if (!match) return false;

  const yy = match[1];
  const mm = match[2];
  const dd = match[3];
  const serial = match[4];

  const yearShort = parseInt(yy, 10);
  const rawMonth = parseInt(mm, 10);
  const day = parseInt(dd, 10);

  // Decode month: men 01-12, women 51-62, from 2004 +20 (men 21-32) / +70 (women 71-82)
  let month: number;
  let offsetUsed = false;
  if (rawMonth >= 1 && rawMonth <= 12) {
    month = rawMonth;
  } else if (rawMonth >= 21 && rawMonth <= 32) {
    month = rawMonth - 20;
    offsetUsed = true;
  } else if (rawMonth >= 51 && rawMonth <= 62) {
    month = rawMonth - 50;
  } else if (rawMonth >= 71 && rawMonth <= 82) {
    month = rawMonth - 70;
    offsetUsed = true;
  } else {
    return false;
  }

  let year: number;

  if (serial.length === 3) {
    // 9-digit form: only for births before 1954
    if (yearShort >= 54) return false;
    if (serial === "000") return false;
    year = 1900 + yearShort;
    // Offset months are only valid from 2004, which cannot apply here
    if (offsetUsed) return false;
  } else {
    // 10-digit form
    year = yearShort < 54 ? 2000 + yearShort : 1900 + yearShort;
    if (offsetUsed && year < 2004) return false;

    // Check digit: first 9 digits mod 11; remainder 10 maps to check digit 0
    const first9 = Number(yy + mm + dd + serial.substring(0, 3));
    const remainder = first9 % 11;
    const expected = remainder === 10 ? 0 : remainder;
    if (expected !== Number(serial.charAt(3))) return false;
  }

  // Validate day of month
  const isLeap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const daysInMonth = [31, isLeap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  const maxDay = daysInMonth[month - 1];
  if (day < 1 || day > maxDay) return false;

  return true;
}

export function solve(id: string): boolean {
  // YYMMDD/SSSS (10 digits) or YYMMDD/SSS (9 digits); the slash is optional.
  const m = /^(\d{2})(\d{2})(\d{2})\/?(\d{3,4})$/.exec(id);
  if (!m) return false;

  const yy = m[1];
  const mm = m[2];
  const dd = m[3];
  const serial = m[4];
  const isTenDigit = serial.length === 4;
  const y = parseInt(yy, 10);

  // Determine the full birth year.
  let year: number;
  if (isTenDigit) {
    year = y < 54 ? 2000 + y : 1900 + y;
  } else {
    // 9-digit form: issued before 1954 only, serial must not be 000.
    if (y >= 54) return false;
    if (serial === '000') return false;
    year = 1900 + y;
  }

  // Decode the month: +50 for women, +20 for men from 2004 (+70 for women from 2004).
  const raw = parseInt(mm, 10);
  let month: number;
  if (raw >= 71 && raw <= 82) {
    if (year < 2004) return false;
    month = raw - 70;
  } else if (raw >= 51 && raw <= 62) {
    month = raw - 50;
  } else if (raw >= 21 && raw <= 32) {
    if (year < 2004) return false;
    month = raw - 20;
  } else {
    month = raw;
  }
  if (month < 1 || month > 12) return false;

  // Validate the day against the month length (Gregorian leap years).
  const day = parseInt(dd, 10);
  const leap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const daysInMonth = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (day < 1 || day > daysInMonth[month - 1]) return false;

  if (isTenDigit) {
    // Modulo-11 check digit validation via the library.
    return lib.isTaxID(yy + mm + dd + serial, 'cs-CZ');
  }

  return true;
}

