const CHECK_CHARS = "0123456789ABCDEFHJKLMNPRSTUVWXY";
const CENTURY: Readonly<Record<string, number>> = {
  "+": 1800,
  "-": 1900,
  "A": 2000,
};

function isLeap(year: number): boolean {
  return (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
}

function daysInMonth(year: number, month: number): number {
  const days = [31, isLeap(year) ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  return days[month - 1];
}

export function solve(hetu: string): boolean {
  if (typeof hetu !== "string" || hetu.length !== 11) {
    return false;
  }

  // Structure: DDMMYY, century sign, 3-digit individual number, check character
  const match = /^(\d{2})(\d{2})(\d{2})([+\-Aa])(\d{3})([0-9A-Z])$/.exec(hetu);
  if (!match) {
    return false;
  }

  const [, dd, mm, yy, rawCentury, indStr, check] = match;

  // Normalize century sign: 'a' is accepted as 'A'
  const centurySign = rawCentury === "a" ? "A" : rawCentury;
  const century = CENTURY[centurySign];
  if (century === undefined) {
    return false;
  }

  // Date of birth must exist
  const day = parseInt(dd, 10);
  const month = parseInt(mm, 10);
  const year = century + parseInt(yy, 10);
  if (month < 1 || month > 12) {
    return false;
  }
  if (day < 1 || day > daysInMonth(year, month)) {
    return false;
  }

  // Individual number range
  const individual = parseInt(indStr, 10);
  if (individual < 2 || individual > 899) {
    return false;
  }

  // Check character: 9-digit number (DDMMYYNNN) modulo 31
  const base = parseInt(dd + mm + yy + indStr, 10);
  const expectedCheck = CHECK_CHARS.charAt(base % 31);
  if (check !== expectedCheck) {
    return false;
  }

  // Delegate to the library with the normalized code
  const normalized = dd + mm + yy + centurySign + indStr + check;
  return lib.isTaxID(normalized, "fi-FI");
}

export function solve(code: string): boolean {
  if (typeof code !== "string") return false;
  const s = code.toUpperCase();
  if (s.length !== 16) return false;

  // Structure: 6 letters, 2 digit-positions, month letter, 2 digit-positions,
  // comune letter, 3 digit-positions, check letter.
  // Digit positions (0-based 6,7,9,10,12,13,14) may hold omocodia letters.
  const OMO = "LMNPQRSTUV"; // L=0, M=1, N=2, P=3, Q=4, R=5, S=6, T=7, U=8, V=9
  const structure =
    /^[A-Z]{6}[0-9LMNPQRSTUV]{2}[ABCDEHLMPRST][0-9LMNPQRSTUV]{2}[A-Z][0-9LMNPQRSTUV]{3}[A-Z]$/;
  if (!structure.test(s)) return false;

  // Surname and given-name codes: consonants first, then vowels, then X padding.
  // Pattern: consonants (X counts as consonant), then vowels, then only X's.
  const nameCode = /^[^AEIOU]*[AEIOU]*X*$/;
  if (!nameCode.test(s.slice(0, 3))) return false;
  if (!nameCode.test(s.slice(3, 6))) return false;

  // Normalize omocodia letters in digit positions back to digits.
  const chars = s.split("");
  for (const idx of [6, 7, 9, 10, 12, 13, 14]) {
    const ch = chars[idx];
    if (ch >= "0" && ch <= "9") continue;
    const v = OMO.indexOf(ch);
    if (v < 0) return false;
    chars[idx] = String(v);
  }
  const n = chars.join("");

  // Month letter: A B C D E H L M P R S T
  const monthLetters = "ABCDEHLMPRST";
  const month = monthLetters.indexOf(n[8]) + 1;
  if (month < 1) return false;

  // Year (two digits) and leap-year rule: divisible by 4 (00 included).
  const year = parseInt(n.slice(6, 8), 10);

  // Day and sex: men 1..31, women 41..71 (day + 40).
  let day = parseInt(n.slice(9, 11), 10);
  if (day >= 41 && day <= 71) {
    day -= 40;
  }
  if (day < 1 || day > 31) return false;

  const leap = year % 4 === 0;
  const daysInMonth = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (day > daysInMonth[month - 1]) return false;

  // Check character over the first 15 characters (digit positions normalized).
  const oddDigit = [1, 0, 5, 7, 9, 13, 15, 17, 19, 21];
  const oddLetter = [
    1, 0, 5, 7, 9, 13, 15, 17, 19, 21, 2, 4, 18, 20, 11,
    3, 6, 8, 12, 14, 16, 10, 22, 25, 24, 23,
  ];

  let sum = 0;
  for (let i = 0; i < 15; i++) {
    const c = n[i];
    const isDigit = c >= "0" && c <= "9";
    if (i % 2 === 0) {
      // Odd position (1-based)
      sum += isDigit ? oddDigit[c.charCodeAt(0) - 48] : oddLetter[c.charCodeAt(0) - 65];
    } else {
      // Even position (1-based)
      sum += isDigit ? c.charCodeAt(0) - 48 : c.charCodeAt(0) - 65;
    }
  }
  const expected = String.fromCharCode(65 + (sum % 26));
  return n[15] === expected;
}

