export function solve(cnp: string): boolean {
  // Shape: exactly 13 decimal digits.
  if (!/^\d{13}$/.test(cnp)) return false;

  // Special case: codes starting with 9000 are accepted with no other check.
  if (cnp.startsWith('9000')) return true;

  // Note: lib.isTaxID is not used. Its generic TIN format cannot express
  // this spec's rules (leading-0 codes and the 9000 bypass), so the
  // checks are implemented directly here.
  const d = cnp.split('').map(Number);

  const s = d[0];
  const yy = d[1] * 10 + d[2];
  const mm = d[3] * 10 + d[4];
  const dd = d[5] * 10 + d[6];

  // Century from the first digit. For 0, 7, 8 and 9 the century is unknown,
  // so the date is checked on the two-digit year alone.
  let fullYear: number | null;
  if (s === 1 || s === 2) fullYear = 1900 + yy;
  else if (s === 3 || s === 4) fullYear = 1800 + yy;
  else if (s === 5 || s === 6) fullYear = 2000 + yy;
  else fullYear = null;

  // Validate the date of birth.
  if (mm < 1 || mm > 12 || dd < 1) return false;

  let leap: boolean;
  if (fullYear !== null) {
    leap =
      fullYear % 4 === 0 && (fullYear % 100 !== 0 || fullYear % 400 === 0);
  } else {
    // Two-digit year only: February 29 allowed when the year is divisible by 4.
    leap = yy % 4 === 0;
  }

  const daysInMonth = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (dd > daysInMonth[mm - 1]) return false;

  // Check digit: weighted sum of the first 12 digits, mod 11; a remainder of 10 gives 1.
  const weights = [2, 7, 9, 1, 4, 6, 3, 5, 8, 2, 7, 9];
  let sum = 0;
  for (let i = 0; i < 12; i++) {
    sum += d[i] * weights[i];
  }
  let check = sum % 11;
  if (check === 10) check = 1;

  return check === d[12];
}

export function solve(id: string): boolean {
  // YYMMDD, optional slash, then a 3-digit (pre-1954) or 4-digit (10-digit form) tail
  const m = /^(\d{2})(\d{2})(\d{2})\/?(\d{3,4})$/.exec(id);
  if (!m) return false;

  const yy = Number(m[1]);
  const monthField = Number(m[2]);
  const day = Number(m[3]);
  const tail = m[4];

  // Decode month: women +50, from 2004 an extra +20 (combined +70)
  let month: number;
  if (monthField >= 71 && monthField <= 82) month = monthField - 70;
  else if (monthField >= 51 && monthField <= 62) month = monthField - 50;
  else if (monthField >= 21 && monthField <= 32) month = monthField - 20;
  else if (monthField >= 1 && monthField <= 12) month = monthField;
  else return false;

  let year: number;
  if (tail.length === 3) {
    // 9-digit form: only for numbers issued before 1954, birth years 1900-1953
    if (yy >= 54) return false;
    if (tail === "000") return false;
    year = 1900 + yy;
  } else {
    // 10-digit form: years below 54 are 20YY, otherwise 19YY
    year = yy < 54 ? 2000 + yy : 1900 + yy;

    const digits = m[1] + m[2] + m[3] + tail; // 10 digits
    const base = Number(digits.slice(0, 9));
    const r = base % 11;
    const check = r === 10 ? 0 : r;
    if (check !== Number(digits[9])) return false;
  }

  // Validate the day against the actual calendar (Gregorian leap years)
  const leap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const daysInMonth = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (day < 1 || day > daysInMonth[month - 1]) return false;

  return true;
}

