  if (!m) return false;

  const day = Number(m[1]);
  const month = Number(m[2]);
  const yy = Number(m[3]);
  const sign = m[4];
  const individual = Number(m[5]);
  const check = m[6];

  const century = sign === "+" ? 1800 : sign === "-" ? 1900 : 2000;
  const year = century + yy;

  const leap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const daysInMonth = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

  if (month < 1 || month > 12) return false;
  if (day < 1 || day > daysInMonth[month - 1]) return false;

  // Individual numbers 002–899 are valid for persons
  if (individual < 2 || individual > 899) return false;

  const CHECK_CHARS = "0123456789ABCDEFHJKLMNPRSTUVWXY";
  const base = Number(m[1] + m[2] + m[3] + m[5]);
  const expected = CHECK_CHARS[base % 31];

  return check === expected;
