export function solve(code: string): boolean {
  if (typeof code !== 'string' || code.length !== 16) return false;

  const s = code.toUpperCase();
  const t: string[] = s.split('');

  // Omocodia: digit positions (0-based) may hold L=0, M=1, N=2, P=3, Q=4, R=5, S=6, T=7, U=8, V=9
  const OMO = 'LMNPQRSTUV';
  const DIGIT_POS = [6, 7, 9, 10, 12, 13, 14];
  const LETTER_POS = [0, 1, 2, 3, 4, 5, 8, 11, 15];

  for (const i of DIGIT_POS) {
    const c = t[i];
    const o = OMO.indexOf(c);
    if (o >= 0) {
      t[i] = String(o);
    } else if (!/^[0-9]$/.test(c)) {
      return false;
    }
  }

  for (const i of LETTER_POS) {
    if (!/^[A-Z]$/.test(t[i])) return false;
  }

  // Surname (0-2) and given name (3-5) codes: consonants, then vowels, then X padding
  const NAME_RE = /^[B-DF-HJ-NP-TV-Z]*[AEIOU]*X*$/;
  if (!NAME_RE.test(t.slice(0, 3).join(''))) return false;
  if (!NAME_RE.test(t.slice(3, 6).join(''))) return false;

  // Month letter
  const MONTHS = 'ABCDEHLMPRST';
  const m = MONTHS.indexOf(t[8]);
  if (m < 0) return false;

  // Year, day (women +40)
  const yy = Number(t[6] + t[7]);
  const raw = Number(t[9] + t[10]);
  const day = raw > 40 ? raw - 40 : raw;
  const leap = yy % 4 === 0;
  const daysInMonth = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (day < 1 || day > daysInMonth[m]) return false;

  // Check character
  const ODD_DIGIT = [1, 0, 5, 7, 9, 13, 15, 17, 19, 21];
  const ODD_LETTER = [
    1, 0, 5, 7, 9, 13, 15, 17, 19, 21, 2, 4, 18,
    20, 11, 3, 6, 8, 12, 14, 16, 10, 22, 25, 24, 23,
  ];

  let sum = 0;
  for (let i = 0; i < 15; i++) {
    const c = t[i];
    const isOdd = i % 2 === 0; // 1-based odd positions
    let v: number;
    if (c >= '0' && c <= '9') {
      const d = c.charCodeAt(0) - 48;
      v = isOdd ? ODD_DIGIT[d] : d;
    } else {
      const l = c.charCodeAt(0) - 65;
      v = isOdd ? ODD_LETTER[l] : l;
    }
    sum += v;
  }

  return String.fromCharCode(65 + (sum % 26)) === t[15];
}

const CENTURY_SIGNS: Record<string, number> = {
  '+': 1800,
  '-': 1900,
  'A': 2000,
};

export function solve(hetu: string): boolean {
  if (typeof hetu !== 'string' || hetu.length !== 11) {
    return false;
  }

  // Accept lowercase 'a' as the century sign for 2000s.
  let normalized = hetu;
  if (normalized[6] === 'a') {
    normalized = normalized.slice(0, 6) + 'A' + normalized.slice(7);
  }

  // Check letter must be upper case.
  const checkChar = normalized[10];
  if (!/^[0-9A-FHJ-NPR-Y]$/.test(checkChar)) {
    return false;
  }

  // Format and check-character validation via the library.
  if (!lib.isTaxID(normalized, 'fi-FI')) {
    return false;
  }

  // Validate that the date of birth actually exists.
  const century = CENTURY_SIGNS[normalized[6]];
  if (century === undefined) {
    return false;
  }

  const day = parseInt(normalized.slice(0, 2), 10);
  const month = parseInt(normalized.slice(2, 4), 10);
  const yy = parseInt(normalized.slice(4, 6), 10);
  const year = century + yy;

  const date = new Date(Date.UTC(year, month - 1, day));
  return (
    date.getUTCFullYear() === year &&
    date.getUTCMonth() === month - 1 &&
    date.getUTCDate() === day
  );
}

