  if (!lib.isTaxID(n, 'it-IT')) return false;

  // Surname and given-name codes
  if (!NAME_BLOCK.test(n.slice(0, 3)) || !NAME_BLOCK.test(n.slice(3, 6))) return false;

  // Month letter
  const month = MONTH_CODES.indexOf(n[8]);
  if (month < 0) return false;

  // Date of birth
  const yy = Number(n.slice(6, 8));
  const dd = Number(n.slice(9, 11));
  const female = dd > 40;
  const day = female ? dd - 40 : dd;
  const leap = yy % 4 === 0; // two-digit years divisible by 4 (00 included)
  const maxDay = month === 1 ? (leap ? 29 : 28) : MONTH_DAYS[month];
  if (day < 1 || day > maxDay) return false;

  // Belfiore code: one letter followed by three digits
  if (!/^[A-Z]\d{3}$/.test(n.slice(11, 15))) return false;

  // Check character
  let sum = 0;
  for (let i = 0; i < 15; i++) {
    sum += charValue(n[i], i % 2 === 0);
  }
  const expected = String.fromCharCode(65 + (sum % 26));
  return n[15] === expected;
}

const CNP_WEIGHTS = [2, 7, 9, 1, 4, 6, 3, 5, 8, 2, 7, 9];
const DAYS_IN_MONTH = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

function isGregorianLeap(year: number): boolean {
  return year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
}

export function solve(cnp: string): boolean {
  // Format check: exactly 13 digits, delegated to the library's ro-RO pattern.
  if (!lib.isTaxID(cnp, 'ro-RO')) {
    return false;
  }

  // A code starting with 9000 is accepted with no further checks.
  if (cnp.slice(0, 4) === '9000') {
    return true;
  }

  const d = cnp.split('').map(Number);

  // Sex/century digit, year (YY), month (MM), day (DD).
  const s = d[0];
  const yy = d[1] * 10 + d[2];
  const mm = d[3] * 10 + d[4];
  const dd = d[5] * 10 + d[6];

  let leap: boolean;
  if (s >= 1 && s <= 6) {
    // Century is determined by the first digit.
    const century = s <= 2 ? 1900 : s <= 4 ? 1800 : 2000;
    leap = isGregorianLeap(century + yy);
  } else {
    // 0, 7, 8, 9: date checked on the two-digit year alone.
    leap = yy % 4 === 0;
  }

  // Date validity.
  if (mm < 1 || mm > 12) {
    return false;
  }
  const maxDay = mm === 2 && leap ? 29 : DAYS_IN_MONTH[mm - 1];
  if (dd < 1 || dd > maxDay) {
    return false;
  }

  // Check digit (mod 11 with remainder 10 mapped to 1).
  let sum = 0;
  for (let i = 0; i < 12; i++) {
    sum += d[i] * CNP_WEIGHTS[i];
  }
  const remainder = sum % 11;
  const expected = remainder === 10 ? 1 : remainder;

  return expected === d[12];
}

const CHECK_CHARS = "0123456789ABCDEFHJKLMNPRSTUVWXY";

export function solve(hetu: string): boolean {
  // DDMMYY, century sign (+, -, A or a), individual number NNN, check character
  const m = /^(\d{2})(\d{2})(\d{2})([+\-Aa])(\d{3})([0-9A-FHJ-NPR-Y])$/.exec(hetu);
  if (!m) return false;

  const day = Number(m[1]);
  const month = Number(m[2]);
  const yy = Number(m[3]);
  const sign = m[4];
  const individual = Number(m[5]);
  const check = m[6];

  let base: number;
  if (sign === "+") {
    base = 1800;
  } else if (sign === "-") {
    base = 1900;
  } else {
    base = 2000; // "A" or "a"
  }
  const year = base + yy;

  // Verify the date actually exists (rejects e.g. 31.02. or 29.02. in non-leap years)
  const date = new Date(Date.UTC(year, month - 1, day));
  if (
    date.getUTCFullYear() !== year ||
    date.getUTCMonth() !== month - 1 ||
    date.getUTCDate() !== day
  ) {
    return false;
  }

  // Individual number range
  if (individual < 2 || individual > 899) return false;

  // Check character: DDMMYYNNN as a number, modulo 31
  const n = Number(m[1] + m[2] + m[3] + m[5]);
  return CHECK_CHARS[n % 31] === check;
}

export function solve(id: string): boolean {
  if (typeof id !== 'string') return false;

  const m = /^(\d{2})(\d{2})(\d{2})\/?(\d{3,4})$/.exec(id);
  if (!m) return false;

  const yy = Number(m[1]);
  let mm = Number(m[2]);
  const dd = Number(m[3]);
  const serial = m[4];
  const digits = m[1] + m[2] + m[3] + serial;
  const is9 = serial.length === 3;

  let year: number;
  if (is9) {
    // Old 9-digit form: only for births before 1954, serial must not be 000
    if (yy >= 54) return false;
    if (serial === '000') return false;
    year = 1900 + yy;
  } else {
    // 10-digit form: two-digit years below 54 are 20YY, otherwise 19YY
    year = yy < 54 ? 2000 + yy : 1900 + yy;
  }

  // Month offsets: +50 for women, +20 for numbers issued from 2004, +70 for both
  let offset = 0;
  if (mm > 70) offset = 70;
  else if (mm > 50) offset = 50;
  else if (mm > 20) offset = 20;

  if ((offset === 20 || offset === 70) && year < 2004) return false;

  mm -= offset;
  if (mm < 1 || mm > 12) return false;

  const leap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const daysInMonth = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (dd < 1 || dd > daysInMonth[mm - 1]) return false;

  if (is9) return true;

  // 10-digit form: delegate the divisibility-by-11 check to the library
  return lib.isTaxID(digits, 'cs-CZ');
}

export function solve(cnp: string): boolean {
  // A code starting with 9000 is accepted with no other check.
  if (cnp.startsWith("9000")) {
    return true;
  }

  // Must be exactly 13 ASCII digits.
  if (!/^\d{13}$/.test(cnp)) {
    return false;
  }

  const d = cnp.split("").map(Number);
  const s = d[0];
  const yy = d[1] * 10 + d[2];
  const mm = d[3] * 10 + d[4];
  const dd = d[5] * 10 + d[6];

  // Determine the year used for the date check.
  // Digits 1-6 carry a century; 0, 7, 8, 9 are checked on the two-digit year alone.
  let leap: boolean;
  if (s === 1 || s === 2) {
    const y = 1900 + yy;
    leap = y % 4 === 0 && (y % 100 !== 0 || y % 400 === 0);
  } else if (s === 3 || s === 4) {
    const y = 1800 + yy;
    leap = y % 4 === 0 && (y % 100 !== 0 || y % 400 === 0);
  } else if (s === 5 || s === 6) {
    const y = 2000 + yy;
    leap = y % 4 === 0 && (y % 100 !== 0 || y % 400 === 0);
  } else {
    leap = yy % 4 === 0;
  }

  // Validate the date of birth.
  if (mm < 1 || mm > 12) {
    return false;
  }
  const daysInMonth = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (dd < 1 || dd > daysInMonth[mm - 1]) {
    return false;
  }

  // Check digit: weighted sum modulo 11; remainder 10 maps to 1.
  const weights = [2, 7, 9, 1, 4, 6, 3, 5, 8, 2, 7, 9];
  let sum = 0;
  for (let i = 0; i < 12; i++) {
    sum += d[i] * weights[i];
  }
  const r = sum % 11;
  const expected = r === 10 ? 1 : r;

  return d[12] === expected;
}

export function solve(id: string): boolean {
  const m = /^(\d{2})(\d{2})(\d{2})\/?(\d{3,4})$/.exec(id);
  if (!m) return false;

  const yy = parseInt(m[1], 10);
  let mm = parseInt(m[2], 10);
  const dd = parseInt(m[3], 10);
  const tail = m[4];

  let year: number;

  if (tail.length === 4) {
    // 10-digit form: check digit must satisfy mod 11 rule (remainder 10 -> check digit 0)
    year = yy < 54 ? 2000 + yy : 1900 + yy;
    const nine = parseInt(m[1] + m[2] + m[3] + tail.slice(0, 3), 10);
    const r = nine % 11;
    const expected = r === 10 ? 0 : r;
    if (parseInt(tail[3], 10) !== expected) return false;
  } else {
    // 9-digit form: only for births 1900-1953, serial must not be 000
    if (yy >= 54) return false;
    if (tail === "000") return false;
    year = 1900 + yy;
  }

  // Month offset: +50 for women, +20 for numbers issued from 2004, +70 for women from 2004
  let offset: number;
  if (mm >= 71 && mm <= 82) {
    offset = 70;
  } else if (mm >= 51 && mm <= 62) {
    offset = 50;
  } else if (mm >= 21 && mm <= 32) {
    offset = 20;
  } else if (mm >= 1 && mm <= 12) {
    offset = 0;
  } else {
    return false;
  }

  if ((offset === 20 || offset === 70) && year < 2004) return false;

  mm -= offset;

  // Validate day of month
  const leap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const daysInMonth = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (dd < 1 || dd > daysInMonth[mm - 1]) return false;

  return true;
}

export function solve(code: string): boolean {
  if (typeof code !== 'string') return false;

  const s = code.toUpperCase();
  if (s.length !== 16) return false;

  // Structural/format check via the library (Italian codice fiscale pattern).
  if (!lib.isTaxID(s, 'it-IT')) return false;

  // Surname/given-name codes: consonants first, then vowels, then X padding.
  const nameGroupOk = (g: string): boolean => /^[^AEIOU]*[AEIOU]*X*$/.test(g);
  if (!nameGroupOk(s.slice(0, 3)) || !nameGroupOk(s.slice(3, 6))) return false;

  // Omocodia: letters in digit positions (1-based 7,8,10,11,13,14,15) stand for digits.
  const OMO: Record<string, string> = {
    L: '0', M: '1', N: '2', P: '3', Q: '4',
    R: '5', S: '6', T: '7', U: '8', V: '9',
  };
  const DIGIT_IDX = [6, 7, 9, 10, 12, 13, 14]; // 0-based indices
  const chars = s.split('');
  for (const i of DIGIT_IDX) {
    const rep = OMO[chars[i]];
    if (rep !== undefined) chars[i] = rep;
  }
  const t = chars.join('');

  // Month letter (0-based index 8).
  const MONTHS: Record<string, number> = {
    A: 1, B: 2, C: 3, D: 4, E: 5, H: 6,
    L: 7, M: 8, P: 9, R: 10, S: 11, T: 12,
  };
  const month = MONTHS[t[8]];
  if (month === undefined) return false;

  // Day of birth (indices 9-10); women have +40.
  let day = parseInt(t.slice(9, 11), 10);
  if (Number.isNaN(day)) return false;
  if (day > 40) day -= 40;

  // Two-digit year (indices 6-7); leap if divisible by 4 (00 included).
  const yy = parseInt(t.slice(6, 8), 10);
  if (Number.isNaN(yy)) return false;
  const leap = yy % 4 === 0;

  const DAYS_IN_MONTH = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (day < 1 || day > DAYS_IN_MONTH[month - 1]) return false;

  // Comune code: one letter followed by three digits (indices 11-14).
  if (!/^[A-Z][0-9]{3}$/.test(t.slice(11, 15))) return false;

  // Check character (index 15), computed over indices 0-14 with decoded digits.
  // Odd positions (1-based) are even 0-based indices; even positions are odd indices.
  const ODD = [1, 0, 5, 7, 9, 13, 15, 17, 19, 21, 2, 4, 18, 20, 11, 3, 6, 8, 12, 14, 16, 10, 22, 25, 24, 23];
  let sum = 0;
  for (let i = 0; i < 15; i++) {
    const c = t[i];
    const isDigit = c >= '0' && c <= '9';
    const v = isDigit ? c.charCodeAt(0) - 48 : c.charCodeAt(0) - 65;
    if (i % 2 === 0) {
      sum += ODD[v];
    } else {
      sum += v;
    }
  }
  const expected = String.fromCharCode(65 + (sum % 26));
  return t[15] === expected;
}

export function solve(code: string): boolean {
  if (typeof code !== "string" || code.length !== 16) return false;
  const s = code.toUpperCase();

  const isLetter = (c: string): boolean => c >= "A" && c <= "Z";
  const isDigit = (c: string): boolean => c >= "0" && c <= "9";

  // Positions 1-6 (indices 0-5): surname and given-name codes must be letters.
  for (let i = 0; i < 6; i++) {
    if (!isLetter(s[i])) return false;
  }

  // Within each 3-letter group, consonants come before vowels, and after a
  // vowel only vowels or X padding may appear.
  const groupOk = (g: string): boolean => {
    let seenVowel = false;
    for (const ch of g) {
      const isVowel = "AEIOU".indexOf(ch) >= 0;
      if (seenVowel && !isVowel && ch !== "X") return false;
      if (isVowel) seenVowel = true;
    }
    return true;
  };
  if (!groupOk(s.slice(0, 3)) || !groupOk(s.slice(3, 6))) return false;

  // Omocodia: digits may be replaced by letters L M N P Q R S T U V (0..9).
  const OMO = "LMNPQRSTUV";
  const digitIdx = [6, 7, 9, 10, 12, 13, 14];
  const decoded: string[] = s.split("");
  const digitVal: number[] = [];
  for (const i of digitIdx) {
    const c = s[i];
    let v: number;
    if (isDigit(c)) {
      v = c.charCodeAt(0) - 48;
    } else {
      const k = OMO.indexOf(c);
      if (k < 0) return false;
      v = k;
    }
    decoded[i] = String(v);
    digitVal[i] = v;
  }

  // Position 9 (index 8): month letter.
  const months = "ABCDEHLMPRST";
  const monthIdx = months.indexOf(s[8]);
  if (monthIdx < 0) return false;

  // Position 12 (index 11): municipality code initial letter.
  if (!isLetter(s[11])) return false;

  // Position 16 (index 15): check character must be a letter.
  if (!isLetter(s[15])) return false;

  // Date of birth.
  const yy = digitVal[6] * 10 + digitVal[7];
  const rawDay = digitVal[9] * 10 + digitVal[10];
  let day = rawDay;
  if (rawDay > 40) day = rawDay - 40;
  if (day < 1 || day > 31) return false;

  const month = monthIdx + 1;
  const leap = yy % 4 === 0;
  const maxDays = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (day > maxDays[month - 1]) return false;

  // Check character.
  const oddTable = [1, 0, 5, 7, 9, 13, 15, 17, 19, 21];
  const oddLetters = [
    1, 0, 5, 7, 9, 13, 15, 17, 19, 21, 2, 4, 18, 20,
    11, 3, 6, 8, 12, 14, 16, 10, 22, 25, 24, 23,
  ];
  const oddVal = (c: string): number =>
    isDigit(c) ? oddTable[c.charCodeAt(0) - 48] : oddLetters[c.charCodeAt(0) - 65];
  const evenVal = (c: string): number =>
    isDigit(c) ? c.charCodeAt(0) - 48 : c.charCodeAt(0) - 65;

  let sum = 0;
  for (let i = 0; i < 15; i++) {
    sum += i % 2 === 0 ? oddVal(decoded[i]) : evenVal(decoded[i]);
  }
  const expected = String.fromCharCode(65 + (sum % 26));
  return s[15] === expected;
}

export function solve(cnp: string): boolean {
  // Structure: exactly 13 decimal digits. This is checked directly rather than
  // through lib.isTaxID, whose locale table isn't available here and which has no
  // CNP date or checksum logic to delegate to.
  if (typeof cnp !== 'string' || !/^\d{13}$/.test(cnp)) return false;

  // Accepted with no further checks.
  if (cnp.startsWith('9000')) return true;

  const d = cnp.split('').map(Number);
  const s = d[0];
  const yy = d[1] * 10 + d[2];
  const mm = d[3] * 10 + d[4];
  const dd = d[5] * 10 + d[6];

  // Century and leap-year determination from the sex/century digit.
  let fullYear: number;
  let leap: boolean;
  if (s === 1 || s === 2) {
    fullYear = 1900 + yy;
  } else if (s === 3 || s === 4) {
    fullYear = 1800 + yy;
  } else if (s === 5 || s === 6) {
    fullYear = 2000 + yy;
  } else {
    // 0, 7, 8, 9: two-digit year alone; February 29 allowed when yy is divisible by 4.
    fullYear = yy;
  }

  if (s >= 1 && s <= 6) {
    leap = (fullYear %4 === 0 && fullYear % 100 !== 0) || fullYear % 400 === 0;
  } else {
    leap = yy % 4 === 0;
  }

  // Validate the date.
  if (mm < 1 || mm > 12) return false;
  const daysInMonth = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (dd < 1 || dd > daysInMonth[mm - 1]) return false;

  // Check digit: weighted sum of the first 12 digits, mod 11; 10 maps to 1.
  const weights = [2, 7, 9, 1, 4, 6, 3, 5, 8, 2, 7, 9];
  let sum = 0;
  for (let i = 0; i < 12; i++) {
    sum += d[i] * weights[i];
  }
  const remainder = sum % 11;
  const expected = remainder === 10 ? 1 : remainder;

  return d[12] === expected;
}

export function solve(hetu: string): boolean {
  if (typeof hetu !== "string") return false;

  // DDMMYY, century sign, 3-digit individual number, check character (upper case only)
  const m = /^(\d{2})(\d{2})(\d{2})([+\-Aa])(\d{3})([0-9A-Y])$/.exec(hetu);
  if (!m) return false;

  const [, dd, mm, yy, signRaw, individual, check] = m;
  const sign = signRaw === "a" ? "A" : signRaw;

  // Century signs: + = 1800s, - = 1900s, A = 2000s
  const centuries: Record<string, number> = { "+": 1800, "-": 1900, "A": 2000 };
  const day = Number(dd);
  const month = Number(mm);
  const year = centuries[sign] + Number(yy);

  // Verify the date actually exists (e.g. rejects 31.02.)
  const date = new Date(Date.UTC(year, month - 1, day));
  if (
    date.getUTCFullYear() !== year ||
    date.getUTCMonth() !== month - 1 ||
    date.getUTCDate() !== day
  ) {
    return false;
  }

  // Delegate format and algorithmic checks to the library, using normalized input
  const normalized = dd + mm + yy + sign + individual + check;
  if (!lib.isTaxID(normalized, "fi-FI")) return false;

  // Check character: DDMMYYNNN as integer, mod 31, indexed into the official table
  const CHECK_CHARS = "0123456789ABCDEFHJKLMNPRSTUVWXY";
  const expected = CHECK_CHARS[Number(dd + mm + yy + individual) % 31];

  return check === expected;
}

export function solve(id: string): boolean {
  if (typeof id !== 'string') return false;

  // Accept YYMMDD/XXXC, YYMMDDXXXC, and the 9-digit YYMMDD/XXX or YYMMDDXXX forms.
  const m = /^(\d{2})(\d{2})(\d{2})\/?(\d{3})(\d?)$/.exec(id);
  if (!m) return false;

  const yy = Number(m[1]);
  const mmRaw = Number(m[2]);
  const dd = Number(m[3]);
  const serial = m[4];
  const check = m[5];

  let year: number;

  if (check !== '') {
    // 10-digit form: must be divisible by 11 (with remainder 10 mapping to check digit 0).
    const first9 = Number(m[1] + m[2] + m[3] + serial);
    const r = first9 % 11;
    const expected = r === 10 ? 0 : r;
    if (Number(check) !== expected) return false;
    year = yy < 54 ? 2000 + yy : 1900 + yy;
  } else {
    // 9-digit form: only for people born 1900-1953, serial must not be 000.
    if (yy >= 54) return false;
    if (serial === '000') return false;
    year = 1900 + yy;
  }

  // Decode month: men 1-12, women +50, from 2004 +20 (men), women +70.
  let month = 0;
  if (mmRaw >= 1 && mmRaw <= 12) {
    month = mmRaw;
  } else if (mmRaw >= 21 && mmRaw <= 32 && year >= 2004) {
    month = mmRaw - 20;
  } else if (mmRaw >= 51 && mmRaw <= 62) {
    month = mmRaw - 50;
  } else if (mmRaw >= 71 && mmRaw <= 82 && year >= 2004) {
    month = mmRaw - 70;
  }
  if (month === 0) return false;

  // Validate day against the month length (Gregorian leap years).
  const leap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const daysInMonth = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (dd < 1 || dd > daysInMonth[month - 1]) return false;

  return true;
}

export function solve(hetu: string): boolean {
  if (typeof hetu !== 'string' || hetu.length !== 11) {
    return false;
  }

  const match = /^(\d{2})(\d{2})(\d{2})([+\-Aa])(\d{3})(.)$/.exec(hetu);
  if (!match) {
    return false;
  }

  const [, dd, mm, yy, century, indiv, check] = match;

  let base: number;
  if (century === '+') {
    base = 1800;
  } else if (century === '-') {
    base = 1900;
  } else {
    // 'A' or 'a'
    base = 2000;
  }

  const day = Number(dd);
  const month = Number(mm);
  const year = base + Number(yy);

  if (month < 1 || month > 12) {
    return false;
  }

  const isLeap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const daysInMonth = [31, isLeap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

  if (day < 1 || day > daysInMonth[month - 1]) {
    return false;
  }

  const individual = Number(indiv);
  if (individual < 2 || individual > 899) {
    return false;
  }

  const num = Number(dd + mm + yy + indiv);
  const table = '0123456789ABCDEFHJKLMNPRSTUVWXY';
  const expected = table.charAt(num % 31);

  return check === expected;
}

export function solve(id: string): boolean {
  if (typeof id !== 'string') return false;
  if (!/^\d{6}\/?\d{3,4}$/.test(id)) return false;
  if (!lib.isTaxID(id, 'cs-CZ')) return false;

  const digits = id.replace('/', '');
