    // 10-digit form: YY < 54 means 20YY, otherwise 19YY
    year = yy < 54 ? 2000 + yy : 1900 + yy;
  }

  // Month offsets: +50 for women, +20 for numbers issued from 2004, +70 for women from 2004
  if (mm > 70) mm -= 70;
  else if (mm > 50) mm -= 50;
  else if (mm > 20) mm -= 20;
  if (mm < 1 || mm > 12) return false;

  const leap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const daysInMonth = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  return dd >= 1 && dd <= daysInMonth[mm - 1];
}

export function solve(cnp: string): boolean {
