  const first = d[0];
  const yy = d[1] * 10 + d[2];
  const mm = d[3] * 10 + d[4];
  const dd = d[5] * 10 + d[6];

  let isLeap: boolean;
  if (first === 0 || first === 7 || first === 8 || first === 9) {
    isLeap = yy % 4 === 0;
  } else {
    let year: number;
    if (first === 1 || first === 2) year = 1900 + yy;
    else if (first === 3 || first === 4) year = 1800 + yy;
    else year = 2000 + yy; // 5 or 6
    isLeap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
  }

  if (mm < 1 || mm > 12) return false;
  const daysInMonth = [31, isLeap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (dd < 1 || dd > daysInMonth[mm - 1]) return false;

  const weights = [2, 7, 9, 1, 4, 6, 3, 5, 8, 2, 7, 9];
  let sum = 0;
  for (let i = 0; i < 12; i++) sum += d[i] * weights[i];
  const remainder = sum % 11;
  const control = remainder === 10 ? 1 : remainder;

  return control === d[12];
}

const MONTHS: { [k: string]: number } = {
  A: 1, B: 2, C: 3, D: 4, E: 5, H: 6, L: 7, M: 8, P: 9, R: 10, S: 11, T: 12,
};

// Letters standing in for digits in digit positions (omocodia)
const OMOCODIA: { [k: string]: string } = {
  L: '0', M: '1', N: '2', P: '3', Q: '4', R: '5', S: '6', T: '7', U: '8', V: '9',
};

// 0-based indexes of digit positions: 7, 8, 10, 11, 13, 14, 15 (1-based)
const DIGIT_INDEXES = [6, 7, 9, 10, 12, 13, 14];

const MONTH_DAYS = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

// Values in odd positions for 0-9 then A-Z
const ODD_VALUES = [
  1, 0, 5, 7, 9, 13, 15, 17, 19, 21,
  2, 4, 18, 20, 11, 3, 6, 8, 12, 14, 16, 10, 22, 25, 24, 23,
];

function valueOf(ch: string, odd: boolean): number {
  const code = ch.charCodeAt(0);
  if (code >= 48 && code <= 57) {
    const d = code - 48;
    return odd ? ODD_VALUES[d] : d;
  }
  const l = code - 65; // 'A' = 0 ... 'Z' = 25
  return odd ? ODD_VALUES[10 + l] : l;
}

function checkCharOf(s: string): string {
  let sum = 0;
  for (let i = 0; i < 15; i++) {
    // 0-based even index corresponds to 1-based odd position
    sum += valueOf(s.charAt(i), i % 2 === 0);
  }
  return String.fromCharCode(65 + (sum % 26));
}

function normalize(code: string): string {
  // Uppercase ASCII letters only, so non-ASCII characters are not mapped to A-Z
  const chars = code.replace(/[a-z]/g, (c) => c.toUpperCase()).split('');
  for (let k = 0; k < DIGIT_INDEXES.length; k++) {
    const i = DIGIT_INDEXES[k];
    const mapped = OMOCODIA[chars[i]];
    if (mapped !== undefined) {
      chars[i] = mapped;
    }
  }
  return chars.join('');
}

export function solve(code: string): boolean {
  if (typeof code !== 'string' || code.length !== 16) {
    return false;
  }

  // Letters in digit positions are replaced by the digits they stand for,
  // so the library sees a plain structure and check character computed correctly.
  const s = normalize(code);

  // Structure (and check character, where the library performs it)
  if (!lib.isTaxID(s, 'it-IT')) {
    return false;
  }

  // Month letter
  const month = MONTHS[s.charAt(8)];
  if (month === undefined) {
    return false;
  }

  // Date of birth: two-digit year, day (+40 for women)
  const year = Number(s.slice(6, 8));
  let day = Number(s.slice(9, 11));
  if (day > 40) {
    day -= 40;
  }
  const maxDay =
    month === 2 ? (year % 4 === 0 ? 29 : 28) : MONTH_DAYS[month - 1];
  if (day < 1 || day > maxDay) {
    return false;
  }

  // Check character
  return s.charAt(15) === checkCharOf(s);
}

export function solve(code: string): boolean {
  if (typeof code !== "string") return false;
  const s = code.toUpperCase();

  // Structure: 6 letters, 2 digit-slot chars (year), month letter,
  // 2 digit-slot chars (day), 1 letter + 3 digit-slot chars (comune), check letter.
  // Digit slots may hold omocodia letters L M N P Q R S T U V (= 0..9).
  if (!/^[A-Z]{6}[0-9LMNPQRSTUV]{2}[ABCDEHLMPRST][0-9LMNPQRSTUV]{2}[A-Z][0-9LMNPQRSTUV]{3}[A-Z]$/.test(s)) {
    return false;
  }

  const OMOCODIA = "LMNPQRSTUV";
  const DIGIT_POS = [6, 7, 9, 10, 12, 13, 14];

  // Normalize omocodia letters in digit positions to the digits they stand for.
  const chars = s.split("");
  for (const i of DIGIT_POS) {
    const c = chars[i];
    if (c >= "0" && c <= "9") continue;
    chars[i] = String(OMOCODIA.indexOf(c));
  }
  const t = chars.join("");

  // Surname (positions 0-2) and given-name (positions 3-5) codes:
  // consonants first, then vowels, padded with X only if fewer than 3 letters.
  const isVowel = (c: string): boolean => "AEIOU".indexOf(c) !== -1;
  const codePartValid = (p: string): boolean => {
    for (let m = 1; m <= 3; m++) {
      const head = p.slice(0, m);
      const tail = p.slice(m);
      if (!/^X*$/.test(tail)) continue;
      let seenVowel = false;
      let ok = true;
      for (const c of head) {
        if (isVowel(c)) {
          seenVowel = true;
        } else if (seenVowel) {
          ok = false;
          break;
        }
      }
      if (ok) return true;
    }
    return false;
  };
  if (!codePartValid(t.slice(0, 3))) return false;
  if (!codePartValid(t.slice(3, 6))) return false;

  // Date of birth.
  const MONTHS = "ABCDEHLMPRST";
  const month = MONTHS.indexOf(t[8]); // 0..11
  if (month < 0) return false;

  const yy = parseInt(t.slice(6, 8), 10);
  let dd = parseInt(t.slice(9, 11), 10);
  if (dd > 40) dd -= 40; // female: day + 40
  const leap = yy % 4 === 0; // 00 counts as divisible by 4
  const daysInMonth = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (dd < 1 || dd > daysInMonth[month]) return false;

  // Check character (positions 1..15, 1-based; odd positions use the odd table).
  const ODD = [1, 0, 5, 7, 9, 13, 15, 17, 19, 21, 2, 4, 18, 20, 11, 3, 6, 8, 12, 14, 16, 10, 22, 25, 24, 23];
  let sum = 0;
  for (let i = 0; i < 15; i++) {
    let c = t[i];
    let code: number;
    if (c >= "0" && c <= "9") {
      code = c.charCodeAt(0) - 48;
      if (i % 2 === 0) {
        // digit d in odd position uses the value of letter A + d
        sum += ODD[code];
      } else {
        sum += code;
      }
    } else {
      code = c.charCodeAt(0) - 65;
      if (i % 2 === 0) {
        sum += ODD[code];
      } else {
        sum += code;
      }
    }
  }
  const expected = String.fromCharCode(65 + (sum % 26));
  return t[15] === expected;
}

const HETU_PATTERN = /^(\d{2})(\d{2})(\d{2})([+\-Aa])(\d{3})([0-9A-Y])$/;
const CHECK_CHARS = "0123456789ABCDEFHJKLMNPRSTUVWXY";
const CENTURIES: Record<string, number> = { "+": 1800, "-": 1900, A: 2000, a: 2000 };

function isLeapYear(year: number): boolean {
  return (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
}

function isExistingDate(year: number, month: number, day: number): boolean {
  if (month < 1 || month > 12 || day < 1) return false;
  const daysInMonth = [
    31,
    isLeapYear(year) ? 29 : 28,
    31, 30, 31, 30, 31, 31, 30, 31, 30, 31,
  ];
  return day <= daysInMonth[month - 1];
}

export function solve(hetu: string): boolean {
  if (typeof hetu !== "string") return false;

  const match = HETU_PATTERN.exec(hetu);
  if (!match) return false;

  const [, dd, mm, yy, sign, nnn, check] = match;

  const year = CENTURIES[sign] + Number(yy);
  const month = Number(mm);
  const day = Number(dd);

  // The date of birth must actually exist.
  if (!isExistingDate(year, month, day)) return false;

  // Check character: the DDMMYYNNN number modulo 31 indexes the check table.
  const digits = Number(dd + mm + yy + nnn);
  if (CHECK_CHARS[digits % 31] !== check) return false;

  // Normalise the century sign ('a' -> 'A') and delegate to the library
  // where a Finnish locale is available. Lowercase check letters are already
  // rejected by the pattern above.
  const normalized = `${dd}${mm}${yy}${sign === "a" ? "A" : sign}${nnn}${check}`;
  try {
    return lib.isTaxID(normalized, "fi-FI");
  } catch {
    // Locale not supported by the library; the local checks above suffice.
    return true;
  }
}

export function solve(id: string): boolean {
  const m = /^(\d{2})(\d{2})(\d{2})\/?(\d{3,4})$/.exec(id);
  if (!m) return false;

  const digits = m[1] + m[2] + m[3] + m[4];
  if (!lib.isTaxID(digits, 'cs-CZ')) return false;

  const yy = Number(m[1]);
  const mm = Number(m[2]);
  const dd = Number(m[3]);
  const tail = m[4];
  const is10 = digits.length === 10;

  let year: number;
  if (is10) {
    year = yy < 54 ? 2000 + yy : 1900 + yy;
  } else {
    if (yy >= 54) return false;
    if (tail === '000') return false;
    year = 1900 + yy;
  }

  let month = mm;
  if (month > 70) month -= 70;
  else if (month > 50) month -= 50;
  else if (month > 20) month -= 20;
  if (month < 1 || month > 12) return false;

  const day = dd > 40 ? dd - 40 : dd;
  const leap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const daysInMonth = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (day < 1 || day > daysInMonth[month - 1]) return false;

  if (is10) {
    const base = Number(digits.slice(0, 9));
    let r = base % 11;
    if (r === 10) r = 0;
    if (r !== Number(digits[9])) return false;
  }

  return true;
}

export function solve(cnp: string): boolean {
  if (cnp.startsWith("9000")) return true;
  if (!/^\d{13}$/.test(cnp)) return false;

  const d = cnp.split("").map(Number);
  const s = d[0];
  const yy = d[1] * 10 + d[2];
  const mm = d[3] * 10 + d[4];
  const dd = d[5] * 10 + d[6];

  let isLeap: boolean;
  if (s === 1 || s === 2 || s === 3 || s === 4 || s === 5 || s === 6) {
    const fullYear = s === 1 || s === 2 ? 1900 + yy : s === 3 || s === 4 ? 1800 + yy : 2000 + yy;
    isLeap = (fullYear % 4 === 0 && fullYear % 100 !== 0) || fullYear % 400 === 0;
  } else {
    // 0, 7, 8, 9: check on two-digit year alone
    isLeap = yy % 4 === 0;
  }

  if (mm < 1 || mm > 12) return false;
  const daysInMonth = [31, isLeap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (dd < 1 || dd > daysInMonth[mm - 1]) return false;

  const weights = [2, 7, 9, 1, 4, 6, 3, 5, 8, 2, 7, 9];
  let sum = 0;
  for (let i = 0; i < 12; i++) {
    sum += d[i] * weights[i];
  }
  const r = sum % 11;
  const check = r === 10 ? 1 : r;

  return check === d[12];
}

declare const lib: { isTaxID(str: string, locale?: string): boolean };

export function solve(cnp: string): boolean {
  // Format gate: delegate to lib.isTaxID for ro-RO, falling back to a plain
  // 13-digit check if that locale is unavailable.
  let formatOk: boolean;
  try {
    formatOk = /^\d{13}$/.test(cnp) && lib.isTaxID(cnp, 'ro-RO');
  } catch {
    formatOk = /^\d{13}$/.test(cnp);
  }
  if (!formatOk) return false;

  // Accepted with no other check.
  if (cnp.startsWith('9000')) return true;

  const digits = cnp.split('').map(Number);
  const first = digits[0];
  const yy = Number(cnp.slice(1, 3));
  const mm = Number(cnp.slice(3, 5));
  const dd = Number(cnp.slice(5, 7));

  let leap: boolean;
  if (first === 1 || first === 2 || first === 3 || first === 4 || first === 5 || first === 6) {
    let year: number;
    if (first === 1 || first === 2) year = 1900 + yy;
    else if (first === 3 || first === 4) year = 1800 + yy;
    else year = 2000 + yy;
    leap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  } else {
    // First digit 0, 7, 8 or 9: two-digit year only.
    leap = yy % 4 === 0;
  }

  const daysInMonth = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (mm < 1 || mm > 12) return false;
  if (dd < 1 || dd > daysInMonth[mm - 1]) return false;

  // Check digit.
  const weights = [2, 7, 9, 1, 4, 6, 3, 5, 8, 2, 7, 9];
  let sum = 0;
  for (let i = 0; i < 12; i++) {
    sum += digits[i] * weights[i];
  }
  const remainder = sum % 11;
  const expected = remainder === 10 ? 1 : remainder;

  return expected === digits[12];
}

export function solve(id: string): boolean {
  const m = /^(\d{2})(\d{2})(\d{2})\/?(\d{3}|\d{4})$/.exec(id);
  if (!m) return false;

  const yy = parseInt(m[1], 10);
  const mo = parseInt(m[2], 10);
  const dd = parseInt(m[3], 10);
  const serial = m[4];

  let year: number;
  if (serial.length === 4) {
    // 10-digit form: two-digit year below 54 means 20YY, otherwise 19YY
    year = yy < 54 ? 2000 + yy : 1900 + yy;
    // The whole 10-digit number must be divisible by 11
    const whole = Number(m[1] + m[2] + m[3] + serial);
    if (whole % 11 !== 0) return false;
  } else {
    // 9-digit form: only for births before 1954, serial must not be 000
    if (yy >= 54) return false;
    year = 1900 + yy;
    if (serial === "000") return false;
  }

  // Month: normal (1-12), women (+50), and from 2004 the +20 (men) and +70 (women) offsets
  let month: number;
  if (mo >= 1 && mo <= 12) {
    month = mo;
  } else if (mo >= 51 && mo <= 62) {
    month = mo - 50;
  } else if (year >= 2004 && mo >= 21 && mo <= 32) {
    month = mo - 20;
  } else if (year >= 2004 && mo >= 71 && mo <= 82) {
    month = mo - 70;
  } else {
    return false;
  }

  // Day must exist in that month of that year
  const leap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const daysInMonth = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (dd < 1 || dd > daysInMonth[month - 1]) return false;

  return true;
}

export function solve(hetu: string): boolean {
  if (typeof hetu !== 'string') return false;

  // DDMMYY C NNN K
  const m = /^(\d{2})(\d{2})(\d{2})([+\-Aa])(\d{3})([0-9A-Z])$/.exec(hetu);
  if (!m) return false;

  const day = parseInt(m[1], 10);
  const month = parseInt(m[2], 10);
  const yy = parseInt(m[3], 10);
  const centurySign = m[4];
  const individual = parseInt(m[5], 10);
  const checkChar = m[6];

  const centuries: Record<string, number> = { '+': 1800, '-': 1900, 'A': 2000, 'a': 2000 };
  const year = centuries[centurySign] + yy;

  // Individual number range
  if (individual < 2 || individual > 899) return false;

  // Existing calendar date
  if (month < 1 || month > 12) return false;
  const leap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const daysInMonth = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (day < 1 || day > daysInMonth[month - 1]) return false;

  // Check character: DDMMYYNNN mod 31
  const base = parseInt(m[1] + m[2] + m[3] + m[5], 10);
  const chars = '0123456789ABCDEFHJKLMNPRSTUVWXY';
  return chars[base % 31] === checkChar;
}

export function solve(hetu: string): boolean {
  if (typeof hetu !== "string") return false;

  // Structure: DDMMYY, century sign, 3-digit individual number, check character.
  const m = /^(\d{2})(\d{2})(\d{2})([+\-Aa])(\d{3})([0-9A-Z])$/.exec(hetu);
  if (!m) return false;

  const [, dd, mm, yy, rawSign, indiv, check] = m;

  // Accept lowercase 'a' as the century sign, normalising it to 'A'.
  const sign = rawSign === "a" ? "A" : rawSign;
  const normalized = dd + mm + yy + sign + indiv + check;

  // Delegate format and checksum validation to the library.
  if (!lib.isTaxID(normalized, "fi-FI")) return false;

  // Century sign determines the century of birth.
  const centuryBase: Record<string, number> = { "+": 1800, "-": 1900, "A": 2000 };
  const year = centuryBase[sign] + parseInt(yy, 10);
  const month = parseInt(mm, 10);
  const day = parseInt(dd, 10);

  // Verify the date exists (handles month lengths and leap years).
  if (month < 1 || month > 12 || day < 1) return false;
  const date = new Date(Date.UTC(year, month - 1, day));
  if (
    date.getUTCFullYear() !== year ||
    date.getUTCMonth() !== month - 1 ||
    date.getUTCDate() !== day
  ) {
    return false;
  }

  // Check character: (DDMMYYNNN) mod 31 indexes into the control table.
  const CHECK_CHARS = "0123456789ABCDEFHJKLMNPRSTUVWXY";
  const base = parseInt(dd + mm + yy + indiv, 10);
  return CHECK_CHARS[base % 31] === check;
}

export function solve(code: string): boolean {
  if (typeof code !== "string" || code.length !== 16) return false;

  const s = code.toUpperCase();
  const chars = s.split("");

  const isAlpha = (c: string): boolean => c >= "A" && c <= "Z";
  const OMO = "LMNPQRSTUV"; // omocodia letters for digits 0..9
  const VOW = "AEIOU";
  const MONTHS = "ABCDEHLMPRST";
  const NUM_IDX = [6, 7, 9, 10, 12, 13, 14];
  const ALPHA_IDX = [0, 1, 2, 3, 4, 5, 8, 11, 15];

  // Digit value of a character in a numeric position (plain digit or omocodia letter), -1 if invalid
  const digitVal = (c: string): number => {
    if (c >= "0" && c <= "9") return c.charCodeAt(0) - 48;
    return OMO.indexOf(c);
  };

  // Surname / given-name code: consonants, then vowels, then X padding
  const validAlpha3 = (t: string): boolean => {
    let seenVowel = false;
    let seenPad = false;
    for (const ch of t) {
      const isVowel = VOW.indexOf(ch) >= 0;
      if (!seenVowel) {
        if (isVowel) seenVowel = true;
        continue; // consonants (including X) before the first vowel
      }
      if (isVowel) {
        if (seenPad) return false;
      } else if (ch === "X") {
        seenPad = true;
      } else {
        return false;
      }
    }
    return true;
  };

  // Structural letter checks
  for (const i of ALPHA_IDX) {
    if (!isAlpha(chars[i])) return false;
  }
  for (const i of NUM_IDX) {
    if (digitVal(chars[i]) < 0) return false;
  }

  if (!validAlpha3(s.slice(0, 3))) return false;
  if (!validAlpha3(s.slice(3, 6))) return false;

  // Birth year (two digits)
  const yy = digitVal(chars[6]) * 10 + digitVal(chars[7]);

  // Month
  const mi = MONTHS.indexOf(chars[8]);
  if (mi < 0) return false;
  const month = mi + 1;

  // Day (women have +40)
  let day = digitVal(chars[9]) * 10 + digitVal(chars[10]);
  if (day >= 41 && day <= 71) {
    day -= 40;
  } else if (!(day >= 1 && day <= 31)) {
    return false;
  }

  // Date existence (leap year if two-digit year divisible by 4, 00 included)
  const leap = yy % 4 === 0;
  const dim = [0, 31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (day < 1 || day > dim[month]) return false;

  // Check character
  const ODD_LETTERS = [1, 0, 5, 7, 9, 13, 15, 17, 19, 21, 2, 4, 18, 20, 11, 3, 6, 8, 12, 14, 16, 10, 22, 25, 24, 23];
  const ODD_DIGITS = [1, 0, 5, 7, 9, 13, 15, 17, 19, 21];

  let sum = 0;
  for (let i = 0; i < 15; i++) {
    const c = chars[i];
    const odd = i % 2 === 0; // 0-based even index = 1-based odd position
    let v: number;
    if (NUM_IDX.indexOf(i) >= 0) {
      const n = digitVal(c);
      v = odd ? ODD_DIGITS[n] : n;
    } else {
      const idx = c.charCodeAt(0) - 65;
      v = odd ? ODD_LETTERS[idx] : idx;
    }
    sum += v;
  }
  const expected = String.fromCharCode(65 + (sum % 26));
  return chars[15] === expected;
}

const CNP_WEIGHTS = [2, 7, 9, 1, 4, 6, 3, 5, 8, 2, 7, 9];

export function solve(cnp: string): boolean {
  // Shape: exactly 13 digits.
  if (!/^\d{13}$/.test(cnp)) return false;

  // A code starting with 9000 is accepted with no other check.
  if (cnp.startsWith('9000')) return true;

  // Format (and library-level checks) for the ro-RO locale. Codes starting
  // with 0 fall outside that locale's pattern, so they skip this gate.
  if (cnp[0] !== '0' && !lib.isTaxID(cnp, 'ro-RO')) return false;

  const d = Array.from(cnp, Number);

  // Check digit: weighted sum mod 11, where a remainder of 10 maps to 0.
  const sum = CNP_WEIGHTS.reduce((acc, w, i) => acc + w * d[i], 0);
  const remainder = sum % 11;
  const expected = remainder === 10 ? 0 : remainder;
  if (expected !== d[12]) return false;

  // Date of birth: YYMMDD starting at index 1.
  const s = d[0];
  const yy = d[1] * 10 + d[2];
  const mm = d[3] * 10 + d[4];
  const dd = d[5] * 10 + d[6];

  let leap: boolean;
  if (s === 0 || s >= 7) {
    // Two-digit year only: February 29 allowed when the year is divisible by 4.
    leap = yy % 4 === 0;
  } else {
    const century = s === 1 || s === 2 ? 1900 : s === 3 || s === 4 ? 1800 : 2000;
    const year = century + yy;
    leap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  }

  const daysInMonth = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (mm < 1 || mm > 12) return false;
  if (dd < 1 || dd > daysInMonth[mm - 1]) return false;

  return true;
}

export function solve(id: string): boolean {
  if (typeof id !== 'string') return false;

  // 6 digits (YYMMDD), optional slash, then 3 digits (pre-1954 form) or 4 digits (10-digit form)
  const m = /^(\d{2})(\d{2})(\d{2})\/?(\d{3}|\d{4})$/.exec(id);
  if (!m) return false;

  const yy = Number(m[1]);
  let month = Number(m[2]);
  const day = Number(m[3]);
  const serial = m[4];
  const tenDigit = serial.length === 4;

  // Decode the month: women add 50, and from 2004 onward the offset is +20 (men) or +70 (women)
  let late = false;
  if (month >= 71 && month <= 82) {
    month -= 70;
    late = true;
  } else if (month >= 51 && month <= 62) {
    month -= 50;
  } else if (month >= 21 && month <= 32) {
    month -= 20;
    late = true;
  }
  if (month < 1 || month > 12) return false;

  // Determine the full year
  let year: number;
  if (tenDigit) {
    // Two-digit year below 54 is 20YY, otherwise 19YY
    year = yy < 54 ? 2000 + yy : 1900 + yy;
    // The +20 / +70 month offsets only apply from 2004 onward
    if (late && year < 2004) return false;
  } else {
    // 9-digit form: only for births before 1954, serial must not be 000
    if (yy >= 54) return false;
    if (late) return false;
    if (serial === '000') return false;
    year = 1900 + yy;
  }

  // Validate day of month (Gregorian leap-year rule)
  const isLeap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  let maxDay: number;
  if (month === 2) {
    maxDay = isLeap ? 29 : 28;
  } else if ([4, 6, 9, 11].indexOf(month) !== -1) {
    maxDay = 30;
  } else {
    maxDay = 31;
  }
  if (day < 1 || day > maxDay) return false;

  // 9-digit form has no check digit
  if (!tenDigit) return true;

  // 10-digit form: divisibility check, delegated to the library
  const digits = m[1] + m[2] + m[3] + serial;
  return lib.isTaxID(digits, 'cs-CZ');
}

const MONTHS = "ABCDEHLMPRST";
const MONTH_DAYS = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
const OMOCODIA: Record<string, number> = { L: 0, M: 1, N: 2, P: 3, Q: 4, R: 5, S: 6, T: 7, U: 8, V: 9 };
const DIGIT_POSITIONS = [6, 7, 9, 10, 12, 13, 14];
// Odd-position values, indexed by alphabet index (A=0 ... Z=25); digits 0-9 map to A-J.
const ODD_VALUES = [1, 0, 5, 7, 9, 13, 15, 17, 19, 21, 2, 4, 18, 20, 11, 3, 6, 8, 12, 14, 16, 10, 22, 25, 24, 23];
// Surname/given-name code: consonants first, then vowels, then X padding.
const NAME_PART = /^[B-DF-HJ-NP-TV-Z]*[AEIOU]*X*$/;

function digitValue(ch: string): number | undefined {
  if (ch >= "0" && ch <= "9") return ch.charCodeAt(0) - 48;
  return OMOCODIA[ch];
}

function checkChar(c: string): string {
  let sum = 0;
  for (let i = 0; i < 15; i++) {
    const ch = c[i];
    const k = ch >= "0" && ch <= "9" ? ch.charCodeAt(0) - 48 : ch.charCodeAt(0) - 65;
    sum += i % 2 === 0 ? ODD_VALUES[k] : k;
  }
  return String.fromCharCode(65 + (sum % 26));
}

export function solve(code: string): boolean {
  if (typeof code !== "string") return false;
  const s = code.toUpperCase();
  if (s.length !== 16) return false;

  // Positional character classes
  for (let i = 0; i < 16; i++) {
    const ch = s[i];
    if (DIGIT_POSITIONS.includes(i)) {
      if (digitValue(ch) === undefined) return false;
    } else if (!(ch >= "A" && ch <= "Z")) {
      return false;
    }
  }

  // Surname and given-name codes
  if (!NAME_PART.test(s.slice(0, 3)) || !NAME_PART.test(s.slice(3, 6))) return false;

  // Year, month, day (female days are offset by 40)
  const yy = (digitValue(s[6]) as number) * 10 + (digitValue(s[7]) as number);
  const monthIdx = MONTHS.indexOf(s[8]);
  if (monthIdx < 0) return false;
  const dd = (digitValue(s[9]) as number) * 10 + (digitValue(s[10]) as number);
  let day: number;
  if (dd >= 1 && dd <= 31) day = dd;
  else if (dd >= 41 && dd <= 71) day = dd - 40;
  else return false;

  // Existing date (two-digit years divisible by 4, including 00, are leap years)
  const leap = yy % 4 === 0;
  const maxDay = monthIdx === 1 && leap ? 29 : MONTH_DAYS[monthIdx];
  if (day > maxDay) return false;

  // Canonical form: omocodia letters read as the digits they stand for
  const canonical = s
    .split("")
    .map((ch, i) => (DIGIT_POSITIONS.includes(i) ? String(digitValue(ch)) : ch))
    .join("");

  // Structural / check-character validation via the library
  if (!lib.isTaxID(canonical, "it-IT")) return false;

  return checkChar(canonical) === s[15];
}

export function solve(code: string): boolean {
  if (typeof code !== 'string' || code.length !== 16) return false;
  const s = code.toUpperCase();

  // Surname and given-name codes: consonants first (up to 3), then vowels, then X padding.
  // X is a consonant, so it may also appear among the leading consonants.
  const NAME_CODE = /^[BCDFGHJ-NP-TV-Z]*[AEIOU]*X*$/;
  if (!NAME_CODE.test(s.slice(0, 3)) || !NAME_CODE.test(s.slice(3, 6))) return false;

  // Omocodia: digit positions (0-based 6, 7, 9, 10, 12, 13, 14) may hold L M N P Q R S T U V
  // standing for digits 0-9. Decode them to digits before further checks.
  const OMOCODIA = 'LMNPQRSTUV';
  const digitSlots = [6, 7, 9, 10, 12, 13, 14];
  const d = s.split('');
  for (const i of digitSlots) {
    const c = d[i];
    const v = OMOCODIA.indexOf(c);
    if (v >= 0) {
      d[i] = String(v);
    } else if (!/^[0-9]$/.test(c)) {
      return false;
    }
  }

  // Comune code letter and check letter.
  if (!/^[A-Z]$/.test(d[11]) || !/^[A-Z]$/.test(d[15])) return false;

  // Month letter: A=Jan, B=Feb, C=Mar, D=Apr, E=May, H=Jun, L=Jul, M=Aug, P=Sep, R=Oct, S=Nov, T=Dec.
  const MONTHS = 'ABCDEHLMPRST';
  const mIdx = MONTHS.indexOf(d[8]);
  if (mIdx < 0) return false;
  const month = mIdx + 1;

  // Day: men 01-31, women 41-71 (day + 40).
  let day = Number(d[9] + d[10]);
  if (day >= 41 && day <= 71) {
    day -= 40;
  } else if (day < 1 || day > 31) {
    return false;
  }

  // Date existence. Two-digit year divisible by 4 (including 00) is a leap year.
  const year = Number(d[6] + d[7]);
  const leap = year % 4 === 0;
  const daysInMonth = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (day > daysInMonth[month - 1]) return false;

  // Format and check character, computed on the decoded (digit-only where required) code.
  return lib.isTaxID(d.join(''), 'it-IT');
}
